std::string create_private_key() {
    RSA* rsa = RSA_new();
    if (!rsa) {
        return nullptr;
    }

    BIGNUM* bn = BN_new();
    if (!bn) {
        RSA_free(rsa);
        return nullptr;
    }

    // Set key length (e.g., 2048 bits)
    BN_set_word(bn, 2048);
    if (!RSA_generate_key_ex(rsa, BN_get_word(bn), 65537, nullptr)) {
        BN_free(bn);
        RSA_free(rsa);
        return nullptr;
    }

    BIO* bio = BIO_new(BIO_s_mem());
    if (!bio) {
        BN_free(bn);
        RSA_free(rsa);
        return nullptr;
    }

    if (!PEM_write_bio_RSAPrivateKey(bio, rsa, nullptr, nullptr, 0, nullptr, nullptr)) {
        BIO_free(bio);
        BN_free(bn);
        RSA_free(rsa);
        return nullptr;
    }

    char* pem_data = nullptr;
    long pem_len = BIO_get_mem_data(bio, &pem_data);
    if (pem_len <= 0) {
        BIO_free(bio);
        BN_free(bn);
        RSA_free(rsa);
        return nullptr;
    }

    std::string result(pem_data, pem_len);

    BIO_free(bio);
    BN_free(bn);
    RSA_free(rsa);

    return result;
}
